llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "SQ 29852, a phosphoryl-containing ACE inhibitor with the closest structural similarity to the query, showed 66% absolute oral bioavailability in humans, directly supporting high F for this phosphinic acid ACE inhibitor scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Quinapril, an ACE inhibitor prodrug, had absolute oral bioavailability of 51.7% in healthy participants, supporting high oral absorption for the ACE inhibitor class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Perindopril, another ACE inhibitor prodrug, had absolute oral bioavailability of about 75% in patients, reinforcing high F for this class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Omapatrilat, a non-prodrug ACE/vasopeptidase inhibitor with multiple polar groups, had 31% absolute oral bioavailability in healthy subjects, showing that an active ACE inhibitor can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Benazeprilat, the active diacid metabolite, reached 27.1-28.5% absolute bioavailability from oral benazepril, supporting that active ACE inhibitor diacids can exceed 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogue (SQ 29852) and multiple ACE inhibitors, including active diacid metabolites, show absolute oral bioavailability above 20%; therefore the query is predicted high, with moderate confidence due to lack of direct fosinoprilat data.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fosinoprilat itself; most evidence comes from prodrugs or other ACE inhibitors.",
    "The closest analogue SQ 29852 is a phosphonate with an amino group, not an exact phosphinate match to the query.",
    "Potential differences in intestinal permeability, efflux, or first-pass metabolism between fosinoprilat and the cited analogues are not directly quantified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

